uint32_t Rgb(COLORREF c){return ((c&255)<<16)|(c&0xFF00)|((c>>16)&255);}
COLORREF Brush(HGDIOBJ h,bool& valid){const auto index=StockIndex(h);valid=true;if(index>=0){switch(index){case WHITE_BRUSH:return RGB(255,255,255);case LTGRAY_BRUSH:return RGB(192,192,192);case GRAY_BRUSH:return RGB(128,128,128);case DKGRAY_BRUSH:return RGB(64,64,64);case BLACK_BRUSH:return 0;case NULL_BRUSH:return CLR_INVALID;case 20:return RGB(240,240,240);default:valid=false;return 0;}}if(uint64_t(h)>0&&uint64_t(h)<=32){const int color=int(uint64_t(h)-1);return color==COLOR_HIGHLIGHT?RGB(0,120,215):color==COLOR_WINDOW?RGB(255,255,255):RGB(240,240,240);}if(auto* o=Obj(h);o&&(o->kind==OBJ_BRUSH||o->kind==OBJ_PEN))return o->color;valid=false;return 0;}
