    gd::Request r;r.op=gd::Op::Create;r.other=uint64_t(parent);r.window.style=style;r.window.exStyle=ex;r.window.bounds={x,y,x+width,y+height};if(!(wide?Wide(static_cast<const wchar_t*>(title),r.window.title,64):Ansi(static_cast<const char*>(title),r.window.title,64)))return Fail(ERROR_NO_UNICODE_TRANSLATION,HWND(nullptr));bool valid=false;r.value=Rgb(Brush(c->background?c->background:Stock(WHITE_BRUSH),valid));if(!valid)return Fail(ERROR_INVALID_HANDLE,HWND(nullptr));const auto e=GuardianDesktopCall(&r);if(e)return Fail(e,HWND(nullptr));Zero(local,sizeof(*local));local->h=reinterpret_cast<HWND>(r.handle);local->cls=c;local->proc=c->proc;local->wide=c->builtin?wide:c->wide;local->icon=c->icon;local->smallIcon=c->smallIcon;Reference(reinterpret_cast<HGDIOBJ>(local->icon),1);Reference(reinterpret_cast<HGDIOBJ>(local->smallIcon),1);local->id=LONG_PTR(menu);local->erase=true;const auto hwnd=local->h;
    wchar_t titleW[64]{};Copy(titleW,r.window.title,sizeof(titleW));char titleA[128]{};WideCharToMultiByte(1252,0,titleW,-1,titleA,128,nullptr,nullptr);char classA[128]{};WideCharToMultiByte(1252,0,reinterpret_cast<const wchar_t*>(c->name),-1,classA,128,nullptr,nullptr);
