    const auto created=Invoke(hwnd,WM_NCCREATE,0,LPARAM(c->wide?static_cast<void*>(&cs):static_cast<void*>(&ca)));if(!Local(hwnd))return nullptr;if(!created){Invoke(hwnd,WM_NCDESTROY,0,0);r.op=gd::Op::Destroy;GuardianDesktopCall(&r);ForgetWindow(*local);SetLastError(ERROR_INVALID_WINDOW_HANDLE);return nullptr;}if(Invoke(hwnd,WM_CREATE,0,LPARAM(c->wide?static_cast<void*>(&cs):static_cast<void*>(&ca)))==-1){UiDestroyWindow(hwnd);return nullptr;}
